const finite=(n,min,max)=>Number.isFinite(n)&&n>=min&&n<=max;
export function bridgeEstimate(o){
 const m=BRIDGE_MATERIALS[o.material];if(!m||!finite(o.length,2,500)||!finite(o.width,1,30)||!finite(o.beamWidth,.08,2)||!finite(o.beamHeight,.15,5)||!Number.isInteger(o.girders)||o.girders<1||o.girders>24||!Number.isInteger(o.supports)||o.supports<0||o.supports>24||!finite(o.vehicle,0,1000)||!finite(o.payload,0,5000)||!finite(o.traffic,1,100000)||!finite(o.years,1,200)||!finite(o.bearing,20,1000)||!['dry','wet','marine'].includes(o.climate))throw Error('Parámetros del puente fuera de rango.');
 const span=o.length/(o.supports+1),E=m.elasticGPa*1e9,I=o.beamWidth*o.beamHeight**3/12,Z=o.beamWidth*o.beamHeight**2/6,deck=.12,area=o.beamWidth*o.beamHeight,ownLoad=(o.width*deck/o.girders+area)*m.density*9.81,P=(o.vehicle+o.payload)*1000*9.81*1.3/o.girders,M=ownLoad*span**2/8+P*span/4,stressMPa=M/Z/1e6,deflection=5*ownLoad*span**4/(384*E*I)+P*span**3/(48*E*I),deflectionLimit=span/400,utilization=stressMPa/m.allowMPa,exposure={dry:1,wet:1.4,marine:1.9}[o.climate],fatigueCycles=m.cycles*(.55/Math.max(.06,utilization))**3,life=Math.min(m.life/exposure,fatigueCycles/(365*o.traffic*exposure)),maxLive=Math.max(0,(m.allowMPa*1e6*Z-ownLoad*span**2/8)*4/span)*o.girders/(1000*9.81*1.3),capacity=Math.max(0,maxLive-o.vehicle),beamVolume=area*o.length*o.girders,deckVolume=o.length*o.width*deck,supportVolume=(o.supports+2)*o.width*1.8,groundPressure=((beamVolume+deckVolume)*m.density*9.81/1000+(o.vehicle+o.payload)*9.81)/((o.supports+2)*o.width*1.6),groundSafe=groundPressure<=o.bearing;
 const cost={wood:Math.ceil(o.length*o.width*.5),stone:Math.ceil(supportVolume*6),iron:Math.ceil((o.supports+2)*8)};cost[m.recipe]=(cost[m.recipe]||0)+Math.ceil((beamVolume+deckVolume)*(o.material==='timber'?5:o.material==='steel'?12:6));
 if(o.material==='reinforced')cost.iron+=Math.ceil(beamVolume*3);const reasons=[];if(utilization>1)reasons.push('Tensión superior a la admisible');if(deflection>deflectionLimit)reasons.push('Flecha excesiva');if(!groundSafe)reasons.push('Cimentación insuficiente');if(life<o.years)reasons.push('Vida estimada menor que la deseada');
 return{span,stressMPa,deflectionMm:deflection*1000,deflectionLimitMm:deflectionLimit*1000,utilization,lifeYears:life,capacityPayloadTonnes:capacity,groundPressureKPa:groundPressure,beamVolume,deckVolume,supportVolume,cost,reasons,ok:!reasons.length,units:{span:'m',stress:'MPa',deflection:'mm',capacity:'t',life:'años'},assumptions:'Viga equivalente, carga centrada, reparto uniforme entre vigas, factor dinámico 1,3 y L/400. Fatiga y materiales calibrados para el juego.'};
}
export function corridorEstimate(o){const mode=TRANSPORT_MODES[o.mode];if(!mode||!finite(o.length,10,100000)||!finite(o.width,1,30)||!finite(o.slope,0,60)||!finite(o.cutDepth,0,8)||!finite(o.cargo,.01,100000)||!['firm','soft','rock'].includes(o.soil))throw Error('Corredor inválido');const factor={firm:1,soft:1.6,rock:2.2}[o.soil],ground=['cart','truck','train'].includes(o.mode),land=ground||o.mode==='horse',volume=ground?o.length*o.width*o.cutDepth:0,usable=volume*(o.soil==='rock'?.65:.2),aggregate=ground?o.length*o.width*(o.mode==='cart'?.12:.3)*factor:0,earthwork=volume*factor,trips=Math.ceil(o.cargo/mode.capacity),hours=o.length/1000/mode.speed,cost=ground?{stone:Math.ceil(aggregate*4),wood:Math.ceil(o.length*.15),...(o.mode==='train'?{iron:Math.ceil(o.length*2.4)}:{})}:{wood:Math.ceil(o.length*(o.mode==='horse'?.01:.03)),stone:Math.ceil(o.length*(o.mode==='horse'?0:.02))},issues=[];if(land&&o.slope>mode.grade)issues.push('Pendiente excesiva para '+mode.name);if(o.mode==='ship')issues.push('Pendiente no aplicable: comprobar calado en estudio marítimo');if(o.mode==='plane')issues.push('Pendiente del corredor no aplicable: comprobar pista y aproximación');return{mode,ground,excavationM3:volume,reusableM3:usable,discardM3:volume-usable,aggregateM3:aggregate,earthwork,tripHours:hours,trips,cost,issues,ok:!(land&&o.slope>mode.grade),reservation:false};}
export function defenseStudy(o){if(!['tower','ballista','cannon','antiair','coastal','shield'].includes(o.type)||!finite(o.slope,0,60)||!finite(o.bearing,20,1000)||!finite(o.visibility,0,360)||!finite(o.supplyDistance,0,10000)||!finite(o.power,0,10000))throw Error('Emplazamiento inválido');const heavy=['cannon','coastal','shield'].includes(o.type),needsPower=['antiair','shield'].includes(o.type),needsSupply=o.type!=='shield',reasons=[];if(o.slope>(heavy?5:12))reasons.push('Hace falta nivelar la plataforma');if(o.bearing<(heavy?150:70))reasons.push('Requiere cimentación mejorada');if(o.visibility<120)reasons.push('Sector de tiro muy limitado');if(o.supplyDistance>800)reasons.push('El abastecimiento está demasiado lejos');if(needsPower&&o.power<30)reasons.push('Falta energía disponible');const cost={stone:Math.ceil((heavy?180:70)*(1+o.slope/10)*(150/Math.max(50,o.bearing))),wood:Math.ceil(40+o.supplyDistance*.04),iron:heavy?100:20};return{ok:!reasons.length,reasons,cost,needsPower,needsSupply,coverage:o.visibility/360,details:'El informe exige exploración, operador, acceso y revisión del terreno antes de autorizar la obra de campaña.'};}
